const fs = require('fs');
const csv = require('csv-parser');

// Read CSV and convert to JSON for Moose ingestion
const events = [];

fs.createReadStream('/data/samples/user_activity_sample.csv')
  .pipe(csv())
  .on('data', (row) => {
    // Convert CSV row to the format expected by Moose
    const event = {
      event_id: row.event_id,
      event_ts: new Date(row.event_ts).toISOString(),
      user_id: row.user_id,
      action: row.action,
      duration_ms: parseFloat(row.duration_ms) || 0  // Default null/empty to 0
    };
    events.push(event);
  })
  .on('end', async () => {
    console.log(`Converting ${events.length} events`);

    // Send each event to Moose ingestion API
    for (const event of events) {
      try {
        const response = await fetch('http://localhost:4000/ingest/UserActivity', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(event)
        });

        if (!response.ok) {
          console.error(`Failed to ingest event ${event.event_id}:`, await response.text());
        } else {
          console.log(`✓ Ingested event ${event.event_id}`);
        }
      } catch (error) {
        console.error(`Error ingesting event ${event.event_id}:`, error.message);
      }
    }

    console.log('Data ingestion complete!');
  });

